 "buis": { "niveau": "moderee", "resume": "Toxique pour les chats, les chiens et surtout les chevaux (ASPCA). Pour les humains, peu toxique mais mieux vaut ne pas en manger.", "animaux": { "chats": "oui", "chiens": "oui", "autres": "Chevaux : douleurs au ventre, difficultés à respirer, convulsions (ASPCA)." }, "humains": { "enfants": "oui", "adultes": "oui", "texte": "Le buis est peu toxique pour les humains. Si un enfant avale une ou deux feuilles, il n'a en général pas de problème. Une grande quantité peut donner mal au ventre, nausées, vomissements, diarrhée. Le contact peut irriter la peau." }, "parties": [ "Feuilles et tiges (partie précise non indiquée par la source)" ], "substances": [ "Alcaloïdes : substances amères qui font vomir et peuvent agir sur le système nerveux" ], "pourquoi": "Le buis fabrique des alcaloïdes très amers pour décourager ceux qui le mangent. Ils irritent le ventre ; chez les gros animaux comme le cheval, ils peuvent être graves.", "symptomes": [ "Vomissements", "Diarrhée", "Chez les chevaux : douleurs, difficulté à respirer, convulsions", "Peau : légère irritation possible" ], "que_faire": [ "Ne fais pas vomir la personne, sauf si un médecin ou le centre antipoison le demande.", "Retire les morceaux de plante de la bouche et rince la bouche avec de l'eau.", "Préviens tout de suite un adulte, qui appelle le centre antipoison de la région (exemples : Paris 01 40 05 48 48, Lyon 04 72 11 69 11) ou le 15.", "Si la personne est mal, a la bouche ou la gorge qui gonfle, respire mal ou perd connaissance : appelle le 15 ou le 112.", "Garde un morceau de la plante ou une photo pour le montrer aux secours.", "Ne fais pas vomir l'animal, sauf si un vétérinaire ou un centre antipoison te le demande.", "Retire les morceaux de plante de sa gueule et ne lui donne ni remède maison ni lait.", "Appelle tout de suite ton vétérinaire (ou le vétérinaire de garde), même si l'animal semble aller bien.", "Emporte un morceau de la plante ou une photo avec toi." ], "precautions": [ "Ne laisse pas les chiens mâchonner la haie de buis.", "Lave-toi les mains après la taille.", "Ne jette pas les tailles de buis là où des chevaux ou des chèvres peuvent les manger." ], "precision": "", "verifie": true, "sources": [ { "titre": "ASPCA - Boxwood", "url": "https://www.aspca.org/node/4663" }, { "titre": "Poison Control (poison.org) - How safe are boxwood plants?", "url": "https://www.poison.org:443/articles/how-safe-are-boxwood-plants-213" } ] },
 "laurier-rose": { "niveau": "elevee", "resume": "Très dangereux, pour tous : toutes les parties sont toxiques pour les humains, les chats, les chiens et les chevaux. À éloigner des enfants et des animaux.", "animaux": { "chats": "oui", "chiens": "oui", "autres": "Toxique pour les chevaux (ASPCA)." }, "humains": { "enfants": "oui", "adultes": "oui", "texte": "Manger les fleurs, les feuilles ou les tiges peut gravement atteindre le coeur et provoquer vomissements, vertiges et troubles de la vue. Il faut une aide médicale tout de suite." }, "parties": [ "Feuilles, fleurs, tiges et brindilles : toutes toxiques" ], "substances": [ "Glycosides cardiotoniques (oléandrine) : des substances qui perturbent le rythme du coeur" ], "pourquoi": "Le laurier-rose se défend avec des poisons du coeur. Même une petite quantité peut dérégler le battement du coeur de l'humain comme de l'animal.", "symptomes": [ "Bave, nausées, vomissements, mal au ventre, diarrhée", "Fatigue, vertiges, confusion", "Coeur trop lent ou irrégulier, tension basse", "Troubles de la vue (halos autour des objets)", "Cas graves : malaise, coma, décès" ], "que_faire": [ "Ne fais pas vomir la personne, sauf si un médecin ou le centre antipoison le demande.", "Retire les morceaux de plante de la bouche et rince la bouche avec de l'eau.", "Préviens tout de suite un adulte, qui appelle le centre antipoison de la région (exemples : Paris 01 40 05 48 48, Lyon 04 72 11 69 11) ou le 15.", "Si la personne est mal, a la bouche ou la gorge qui gonfle, respire mal ou perd connaissance : appelle le 15 ou le 112.", "Garde un morceau de la plante ou une photo pour le montrer aux secours.", "Ne fais pas vomir l'animal, sauf si un vétérinaire ou un centre antipoison te le demande.", "Retire les morceaux de plante de sa gueule et ne lui donne ni remède maison ni lait.", "Appelle tout de suite ton vétérinaire (ou le vétérinaire de garde), même si l'animal semble aller bien.", "Emporte un morceau de la plante ou une photo avec toi.", "Si la sève touche la peau ou les yeux : rince longuement à l'eau claire, puis demande conseil à un adulte ou à un médecin si ça pique encore." ], "precautions": [ "Ne l'installe pas là où jouent de jeunes enfants ou des animaux.", "Mets des gants pour tailler et lave-toi les mains.", "Ne brûle jamais ses branches (fumée dangereuse) et ne les utilise pas pour des brochettes ou en cuisine." ], "precision": "Ne pas brûler le bois : conseil de prudence, source non ouverte pour ce point précis.", "verifie": true, "sources": [ { "titre": "ASPCA - Oleander", "url": "https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/oleander" }, { "titre": "MedlinePlus - Oleander poisoning", "url": "https://medlineplus.gov/ency/article/002884.htm" } ] },
