 "rhododendron": { "niveau": "elevee", "resume": "Dangereux : toxique pour les chats, les chiens et les chevaux (quelques feuilles peuvent suffire, ASPCA) et pour les humains (fleurs, feuilles, nectar, miel).", "animaux": { "chats": "oui", "chiens": "oui", "autres": "Toxique pour les chevaux (ASPCA)." }, "humains": { "enfants": "oui", "adultes": "oui", "texte": "Les enfants qui sucent les fleurs ou mâchent les feuilles ont en général une irritation de la bouche et des vomissements. En grande quantité, le poison peut faire tomber la tension et dérégler le coeur. Le miel fait par des abeilles sur ces fleurs peut aussi être toxique." }, "parties": [ "Feuilles, fleurs et nectar", "Miel fait à partir du nectar" ], "substances": [ "Grayanotoxines : poisons qui agissent sur les nerfs et le coeur" ], "pourquoi": "Le rhododendron et l'azalée protègent leurs feuilles et leur nectar avec des grayanotoxines. Elles perturbent les nerfs et le coeur de celui qui les mange.", "symptomes": [ "Irritation de la bouche, nausées, vomissements, bave", "Diarrhée, faiblesse, perte d'équilibre", "Tension basse, coeur lent ou irrégulier", "Cas graves : coma, arrêt du coeur" ], "que_faire": [ "Ne fais pas vomir la personne, sauf si un médecin ou le centre antipoison le demande.", "Retire les morceaux de plante de la bouche et rince la bouche avec de l'eau.", "Préviens tout de suite un adulte, qui appelle le centre antipoison de la région (exemples : Paris 01 40 05 48 48, Lyon 04 72 11 69 11) ou le 15.", "Si la personne est mal, a la bouche ou la gorge qui gonfle, respire mal ou perd connaissance : appelle le 15 ou le 112.", "Garde un morceau de la plante ou une photo pour le montrer aux secours.", "Ne fais pas vomir l'animal, sauf si un vétérinaire ou un centre antipoison te le demande.", "Retire les morceaux de plante de sa gueule et ne lui donne ni remède maison ni lait.", "Appelle tout de suite ton vétérinaire (ou le vétérinaire de garde), même si l'animal semble aller bien.", "Emporte un morceau de la plante ou une photo avec toi." ], "precautions": [ "Ne laisse pas les enfants sucer les fleurs (on les confond avec le chèvrefeuille).", "Garde les animaux loin des massifs.", "Ne mange pas de miel inconnu de montagne ou de petite production sans raison sûre." ], "precision": "", "verifie": true, "sources": [ { "titre": "ASPCA - Rhododendron", "url": "https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/rhododendron" }, { "titre": "Poison Control (poison.org) - Azaleas and rhododendrons", "url": "https://www.poison.org/articles/azaleas-and-rhododendrons" } ] },
 "clematite": { "niveau": "faible", "resume": "Toxique pour les chats, les chiens et les chevaux (ASPCA) : la sève irrite la bouche et le ventre. Pour les humains, aucune source ouverte.", "animaux": { "chats": "oui", "chiens": "oui", "autres": "Toxique pour les chevaux (ASPCA)." }, "humains": { "enfants": "inconnu", "adultes": "inconnu", "texte": "Aucune source ouverte ne parle des humains : par prudence, ne pas la manger. La sève fraîche des clématites est connue pour irriter la peau (non confirmé ici)." }, "parties": [ "Plante fraîche entière (partie précise non indiquée par la source)" ], "substances": [ "Glycoside irritant (protoanémonine) : irrite la bouche, l'estomac et la peau" ], "pourquoi": "La clématite se défend avec une substance qui brûle la bouche et le ventre quand on la mâche. Elle fait cracher et vomir celui qui la goûte.", "symptomes": [ "Bave abondante", "Vomissements", "Diarrhée" ], "que_faire": [ "Ne fais pas vomir la personne, sauf si un médecin ou le centre antipoison le demande.", "Retire les morceaux de plante de la bouche et rince la bouche avec de l'eau.", "Préviens tout de suite un adulte, qui appelle le centre antipoison de la région (exemples : Paris 01 40 05 48 48, Lyon 04 72 11 69 11) ou le 15.", "Si la personne est mal, a la bouche ou la gorge qui gonfle, respire mal ou perd connaissance : appelle le 15 ou le 112.", "Garde un morceau de la plante ou une photo pour le montrer aux secours.", "Ne fais pas vomir l'animal, sauf si un vétérinaire ou un centre antipoison te le demande.", "Retire les morceaux de plante de sa gueule et ne lui donne ni remède maison ni lait.", "Appelle tout de suite ton vétérinaire (ou le vétérinaire de garde), même si l'animal semble aller bien.", "Emporte un morceau de la plante ou une photo avec toi.", "Si la sève touche la peau ou les yeux : rince longuement à l'eau claire, puis demande conseil à un adulte ou à un médecin si ça pique encore." ], "precautions": [ "Mets des gants pour tailler : la sève irrite.", "Ne laisse pas animaux et enfants mâcher les tiges." ], "precision": "Les sources ouvertes ne précisent pas les parties toxiques.", "verifie": true, "sources": [ { "titre": "ASPCA - Clematis (Virgin's Bower)", "url": "https://www.aspca.org/pet-care/aspca-poison-control/toxic-and-non-toxic-plants/clematis" } ] },
